WITH RECURSIVE VisitTxns AS (SELECT v.user_id, v.visit_date, COUNT(t.transaction_date) AS txn_count FROM Visits v LEFT JOIN Transactions t ON v.user_id = t.user_id AND v.visit_date = t.transaction_date GROUP BY v.user_id, v.visit_date), MaxVal AS (SELECT IFNULL(MAX(txn_count), 0) AS max_n FROM VisitTxns), Numbers AS (SELECT 0 AS n UNION ALL SELECT n + 1 FROM Numbers, MaxVal WHERE n < max_n) SELECT num.n AS transactions_count, COUNT(vt.user_id) AS visits_count FROM Numbers num LEFT JOIN VisitTxns vt ON num.n = vt.txn_count GROUP BY num.n ORDER BY num.n;
